package com.dtm.platform.security;
import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.security.crypto.password.*;import org.springframework.security.crypto.bcrypt.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;import org.springframework.web.cors.*;import javax.crypto.spec.SecretKeySpec;import java.util.*;import com.nimbusds.jose.jwk.source.ImmutableSecret;
@Configuration @EnableMethodSecurity public class SecurityConfig {
 @Value("${app.jwt-secret}") String secret;@Value("${app.jwt-issuer}") String issuer;@Value("${app.cors-origins}") String origins;@Value("${app.otp.allowed-phones:}") String phones;
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 private SecretKeySpec key(){byte[] bytes;try{bytes=Base64.getDecoder().decode(secret);}catch(Exception e){throw new IllegalStateException("JWT_SECRET must be base64");}if(bytes.length<32)throw new IllegalStateException("JWT_SECRET must contain at least 32 random bytes");return new SecretKeySpec(bytes,"HmacSHA256");}
 @Bean JwtEncoder encoder(){return new NimbusJwtEncoder(new ImmutableSecret<>(key()));}
 @Bean JwtDecoder decoder(){var decoder=NimbusJwtDecoder.withSecretKey(key()).macAlgorithm(MacAlgorithm.HS256).build();var subjects=OtpIdentity.allowed(phones).stream().map(x->"otp:"+OtpIdentity.hash(x)).collect(java.util.stream.Collectors.toSet());
  org.springframework.security.oauth2.core.OAuth2TokenValidator<Jwt> otp=jwt->"otp".equals(jwt.getClaimAsString("authMethod"))&&subjects.contains(jwt.getSubject())?org.springframework.security.oauth2.core.OAuth2TokenValidatorResult.success():org.springframework.security.oauth2.core.OAuth2TokenValidatorResult.failure(new org.springframework.security.oauth2.core.OAuth2Error("invalid_token"));
  decoder.setJwtValidator(new org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator<>(JwtValidators.createDefaultWithIssuer(issuer),otp));return decoder;}
 @Bean SecurityFilterChain chain(HttpSecurity http,RateLimitFilter limiter)throws Exception{
  var authorities=new JwtGrantedAuthoritiesConverter();authorities.setAuthoritiesClaimName("roles");authorities.setAuthorityPrefix("ROLE_");var converter=new JwtAuthenticationConverter();converter.setJwtGrantedAuthoritiesConverter(authorities);
  http.cors(c->c.configurationSource(cors())).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/v1/admin/**","/api/v1/auth/me","/api/v1/auth/users/**").authenticated().requestMatchers("/api/v1/**","/actuator/health","/v3/api-docs/**","/swagger-ui/**","/swagger-ui.html").permitAll().anyRequest().denyAll()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter))).headers(h->h.contentSecurityPolicy(c->c.policyDirectives("default-src 'none'; frame-ancestors 'none'")).referrerPolicy(r->r.policy(org.springframework.security.web.header.writers.ReferrerPolicyHeaderWriter.ReferrerPolicy.NO_REFERRER))).addFilterBefore(limiter,UsernamePasswordAuthenticationFilter.class);
  return http.build();
 }
 @Bean org.springframework.boot.web.servlet.FilterRegistrationBean<RateLimitFilter> limiterRegistration(RateLimitFilter filter){var registration=new org.springframework.boot.web.servlet.FilterRegistrationBean<>(filter);registration.setEnabled(false);return registration;}
 @Bean @org.springframework.core.annotation.Order(0) SecurityFilterChain docsChain(HttpSecurity http)throws Exception{http.securityMatcher("/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").authorizeHttpRequests(a->a.anyRequest().permitAll()).headers(h->h.contentSecurityPolicy(c->c.policyDirectives("default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; frame-ancestors 'none'")));return http.build();}
 @Bean CorsConfigurationSource cors(){var c=new CorsConfiguration();c.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::trim).toList());c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Content-Type","Authorization","Idempotency-Key"));c.setAllowCredentials(false);var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/api/**",c);return source;}
}
